import math

class Vec:
    EPS = 1e-9

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def add(self, o):
        return Vec(self.x + o.x, self.y + o.y)

    def sub(self, o):
        return Vec(self.x - o.x, self.y - o.y)

    def scale(self, s):
        return Vec(self.x * s, self.y * s)

    def dot(self, o):
        return self.x * o.x + self.y * o.y

    def mag2(self):
        return self.dot(self)

    def mag(self):
        return math.sqrt(self.mag2())

    def unit(self):
        return self.scale(1 / self.mag())

    def rot90(self):
        return Vec(-self.y, self.x)

    def rot270(self):
        return Vec(self.y, -self.x)

    def __eq__(self, o):
        if not isinstance(o, Vec):
            return False
        return self.eq(self.x, o.x) and self.eq(self.y, o.y)

    def __str__(self):
        return "(" + "{:.2f}".format(self.x) + ", " + "{:.2f}".format(self.y) + ")"

    @staticmethod
    def eq(a, b):
        return abs(a - b) < Vec.EPS


class Circle:
    def __init__(self, c, r):
        self.c = c
        self.r = r

    def intersect(self, o):
        if self.c == o.c:
            return None
        d = o.c.sub(self.c)
        dist2 = d.mag2()
        dist = math.sqrt(dist2)
        if self.r + o.r < dist or self.r + dist < o.r or o.r + dist < self.r:
            return None
        if Vec.eq(self.r + o.r, dist) or Vec.eq(o.r + dist, self.r):
            return [self.c.add(d.scale(self.r / dist))]
        if Vec.eq(self.r + dist, o.r):
            return [self.c.sub(d.scale(self.r / dist))]
        d1 = (self.r * self.r + dist2 - o.r * o.r) / (2 * dist)
        h = math.sqrt(self.r * self.r - d1 * d1)
        uDir = d.unit()
        rInt = self.c.add(uDir.scale(d1).add(uDir.rot270().scale(h)))
        lInt = self.c.add(uDir.scale(d1).add(uDir.rot90().scale(h)))
        return [rInt, lInt]


def main():
    n = int(input())
    circles = []
    for _ in range(n):
        parts = input().split()
        x = int(parts[0])
        y = int(parts[1])
        r = int(parts[2])
        circles.append(Circle(Vec(x, y), r))
    allPoints = []
    parent = list(range(n))
    count = 1
    for i in range(n):
        newPoints = []
        for j in range(n):
            if i == j:
                continue
            inters = circles[i].intersect(circles[j])
            if inters is None:
                continue
            a = parent[i]
            b = parent[j]
            parent[a] = parent[parent[a]]
            parent[b] = parent[parent[b]]
            parent[a] = b
            for v in inters:
                exists = False
                for e in newPoints:
                    if v == e:
                        exists = True
                        break
                if not exists:
                    newPoints.append(v)
        count += len(newPoints)
        for v in newPoints:
            if any(v == e for e in allPoints):
                continue
            allPoints.append(v)
    count -= len(allPoints)
    for i in range(n):
        count += 1 - abs((i - parent[i]) // abs(i - parent[i]) if i != parent[i] else 0)
    print(count)

if __name__ == "__main__":
    main()

